import { realpathSync, statSync } from "node:fs";
import { basename, extname, isAbsolute, sep } from "node:path";
import * as z from "zod/v4";
import { SLACK_FILE_ALT_TEXT_MAX_LEN, SLACK_FILE_INITIAL_COMMENT_MAX_LEN, } from "../../../channels/slack/constants.js";
import { defineTool } from "../../../tools.js";
const ALLOWED = new Set([
    ".png",
    ".jpg",
    ".jpeg",
    ".gif",
    ".webp",
    ".svg",
    ".pdf",
    ".html",
    ".txt",
    ".log",
    ".json",
    ".csv",
    ".md",
    ".mp4",
    ".mov",
    ".webm",
]);
const MAX_BYTES = 50 * 1024 * 1024;
function human(bytes) {
    return bytes < 1024 * 1024
        ? `${Math.round(bytes / 1024)} KB`
        : `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}
function caption(value, max) {
    if (value === undefined) {
        return { ok: true };
    }
    const text = value.trim();
    if (text === "") {
        return { ok: true };
    }
    if (text.length > max) {
        return { ok: false };
    }
    return { ok: true, text };
}
const postFile = defineTool({
    description: [
        "Attach a file to the final reply.",
        "Nothing is posted when you call this: the file is staged, and everything",
        "staged is uploaded once, after the reply.",
        "Use it for evidence worth keeping, not for text you could write in the reply.",
        "alt_txt describes an image for screen readers. initial_comment is the text posted with the file.",
        "A failed upload comes back as a later message in the thread. Say which files were not posted, and do not call post-file again in that turn.",
    ].join(" "),
    inputSchema: z.object({
        path: z
            .string()
            .min(1)
            .describe("Absolute path to the file. Relative paths are rejected: this runs on the host, not in the agent shell."),
        alt_txt: z
            .string()
            .trim()
            .max(SLACK_FILE_ALT_TEXT_MAX_LEN)
            .optional()
            .describe("Alt text for an image. Optional. Slack keeps at most 1000 characters."),
        initial_comment: z
            .string()
            .trim()
            .max(SLACK_FILE_INITIAL_COMMENT_MAX_LEN)
            .optional()
            .describe("Text posted with the file. Optional. Files that share this text are uploaded together."),
    }),
    execute: ({ path, alt_txt, initial_comment }, ctx) => {
        if (!isAbsolute(path)) {
            return `Refused: "${path}" is not absolute. Give the full path.`;
        }
        let realPath;
        try {
            realPath = realpathSync(path);
        }
        catch {
            return `No such file: ${path}`;
        }
        const workspaceRoot = realpathSync(ctx.workspaceDir);
        if (realPath !== workspaceRoot && !realPath.startsWith(`${workspaceRoot}${sep}`)) {
            return `Refused: ${path} is outside ${ctx.workspaceDir}. Copy it into your workspace first.`;
        }
        const extension = extname(realPath).toLowerCase();
        if (!ALLOWED.has(extension)) {
            return `Refused: ${extension || "no extension"} is not a type Slack renders. Allowed: ${[...ALLOWED].join(", ")}.`;
        }
        const info = statSync(realPath);
        if (!info.isFile()) {
            return `Refused: ${path} is not a file.`;
        }
        if (info.size > MAX_BYTES) {
            return `Refused: ${human(info.size)} is over the ${human(MAX_BYTES)} upload cap.`;
        }
        const altTxt = caption(alt_txt, SLACK_FILE_ALT_TEXT_MAX_LEN);
        if (!altTxt.ok) {
            return `Refused: alt_txt is over ${SLACK_FILE_ALT_TEXT_MAX_LEN} characters.`;
        }
        const initialComment = caption(initial_comment, SLACK_FILE_INITIAL_COMMENT_MAX_LEN);
        if (!initialComment.ok) {
            return `Refused: initial_comment is over ${SLACK_FILE_INITIAL_COMMENT_MAX_LEN} characters.`;
        }
        const staged = {
            path: realPath,
            name: basename(realPath),
            workspace: workspaceRoot,
        };
        if (altTxt.text !== undefined) {
            staged.alt_txt = altTxt.text;
        }
        if (initialComment.text !== undefined) {
            staged.initial_comment = initialComment.text;
        }
        return staged;
    },
});
export default postFile;
